import{_ as a,c as s,o as n,am as t}from"./chunks/framework.BJtUKP3U.js";const h=JSON.parse('{"title":"预设文件、图片与继承","description":"","frontmatter":{"prev":{"text":"接口参考","link":"/docs/pogget/custom-vina/reference"},"next":{"text":"Pogget_Std 字段表","link":"/docs/pogget/custom-vina/standard-fields"}},"headers":[],"relativePath":"docs/pogget/custom-vina/presets.md","filePath":"docs/pogget/custom-vina/presets.md"}'),o={name:"docs/pogget/custom-vina/presets.md"};function d(p,e,c,l,i,r){return n(),s("div",null,e[0]||(e[0]=[t(`<h1 id="预设文件、图片与继承" tabindex="-1">预设文件、图片与继承 <a class="header-anchor" href="#预设文件、图片与继承" aria-label="Permalink to &quot;预设文件、图片与继承&quot;">​</a></h1><h2 id="预设目录" tabindex="-1">预设目录 <a class="header-anchor" href="#预设目录" aria-label="Permalink to &quot;预设目录&quot;">​</a></h2><p>预设位于用户数据目录下的 <code>Presets/Personalization</code>。Pogget 查找该目录中的 <code>.vina</code>，也查找直接子文件夹中的 <code>.vina</code>；不会继续扫描更深层目录。图片等配套资源可与预设放在一起。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Presets/Personalization/</span></span>
<span class="line"><span>  Pogget_Std.vina             # 名称：Pogget_Std</span></span>
<span class="line"><span>  Blue.vina                   # 名称：Blue</span></span>
<span class="line"><span>  MyTheme/</span></span>
<span class="line"><span>    Blue.vina                 # 名称：MyTheme/Blue</span></span>
<span class="line"><span>    images/background.png</span></span>
<span class="line"><span>    nested/Hidden.vina        # 不会出现在列表中，也不能作为依赖</span></span></code></pre></div><p>名称不含 <code>.vina</code> 扩展名。子目录名称以 <code>文件夹/预设名</code> 表示，所以根目录与子目录可以有同名预设；Windows 下名称不区分大小写，<code>/</code> 与 <code>\\</code> 表示相同的分隔。不能使用绝对路径、<code>..</code>、空目录段、Windows 保留文件名或超过一级的子目录。隐藏、系统和重解析项不参与枚举；子目录不跟随符号链接或目录联接。</p><h2 id="加载外部图片" tabindex="-1">加载外部图片 <a class="header-anchor" href="#加载外部图片" aria-label="Permalink to &quot;加载外部图片&quot;">​</a></h2><p><code>type: &quot;image&quot;</code> 默认用现有 WIC 后端读取本地文件，支持 PNG、JPEG 等已安装 WIC 解码器可识别的格式。相对路径以<strong>声明该图片来源的预设文件所在文件夹</strong>为基准，与程序工作目录无关。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Wallpaper {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;image&quot;,</span></span>
<span class="line"><span>    source: &quot;images/background.png&quot;,</span></span>
<span class="line"><span>    x: 16, y: 64, width: 240, height: 160,</span></span>
<span class="line"><span>    imageFit: &quot;contain&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果上面的预设位于 <code>MyTheme/Blue.vina</code>，图片位置就是 <code>MyTheme/images/background.png</code>。也可用 <code>../shared/banner.png</code> 相对上级目录，或 <code>&quot;D:/Pictures/banner.png&quot;</code> 这样的完整路径；字符串中的反斜杠须写成 <code>\\\\</code>。不支持 <code>C:banner.png</code> 这种依赖当前盘符工作目录的写法，也不下载 HTTP 图片。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型、默认值与用途</th></tr></thead><tbody><tr><td><code>source</code></td><td>字符串；WIC 使用本地绝对/相对文件路径，Shell 使用原始文件路径或图标标识，资源后端使用宿主资源名；可引用文本变量，如 <code>\${pogget.hoveredIcon.path}</code></td></tr><tr><td><code>src</code></td><td><code>source</code> 的兼容别名，显式 <code>source</code> 优先</td></tr><tr><td><code>imageRenderer</code></td><td>默认 <code>&quot;wic&quot;</code>；<code>&quot;shell&quot;</code> 读取文件、文件夹或 Shell 项目的系统图标；<code>&quot;resource&quot;</code> 读取宿主本次登记的命名位图</td></tr><tr><td><code>imageFit</code></td><td>默认 <code>&quot;stretch&quot;</code> 拉伸；<code>&quot;contain&quot;</code> 保持比例，完整居中放入目标区域</td></tr></tbody></table><p>WIC 图片继承后继续相对父预设目录解析；在子预设中重新声明 <code>source</code> 后，该来源相对子预设目录解析。复制为独立预设时，WIC 字面量图片路径会展开为完整路径；使用表达式动态生成的相对路径则以新文件所在目录为基准。</p><p>Shell 来源保持原样传入原生图标后端，不拼接预设目录，也不规范化路径。请使用完整文件路径、宿主 <code>\${pogget.fileIcon.path}</code>，或原生支持的标识，例如 <code>icon@computer.pogget</code>、<code>shell:AppsFolder\\应用标识</code>、<code>::{GUID}</code>。复制预设也会保留这些 Shell 来源及宿主命名资源。</p><p>位图按渲染目标和解析后的路径缓存，设备/路径或预设重新加载时重建。找不到文件、解码失败、空来源都跳过该图片；修复或替换文件后可点“重新加载”。单张图片最多 16,777,216 像素，宽高同时受当前渲染目标最大位图尺寸限制。AI 隔离预览只允许程序生成的样本图片，不会读取真实本地图片。</p><p>完整的裁切、缩放、圆角字段见<a href="./reference.html#图片与同步内容">图片与同步内容</a>。</p><h2 id="为父预设指定参数" tabindex="-1">为父预设指定参数 <a class="header-anchor" href="#为父预设指定参数" aria-label="Permalink to &quot;为父预设指定参数&quot;">​</a></h2><p>在子预设顶部的 <code>Preset</code> 声明中用 <code>parentValues</code> 指定父预设控件的初始值。它覆盖当前子预设对原生配置的读取，不需要用户先切回父预设调整设置，也不改写父预设文件或其他预设的参数。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset {</span></span>
<span class="line"><span>  dependsOn: &quot;Pogget_Std&quot;,</span></span>
<span class="line"><span>  disableParentPreset: true,</span></span>
<span class="line"><span>  parentValues {</span></span>
<span class="line"><span>    Background.ui.RenderStyle: 4,</span></span>
<span class="line"><span>    Background.ui.CornerRadius: 18,</span></span>
<span class="line"><span>    Tag.ui.TitleStyle: 2,</span></span>
<span class="line"><span>    VinaIcon.ui.IconBackground: true,</span></span>
<span class="line"><span>    VinaIcon.ui.IconBackgroundOpacity: 0.20</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MyControls {</span></span>
<span class="line"><span>  label: &quot;我的样式&quot;,</span></span>
<span class="line"><span>  ui {</span></span>
<span class="line"><span>    Strength {</span></span>
<span class="line"><span>      label: &quot;装饰强度&quot;, type: &quot;number&quot;, control: &quot;slider&quot;,</span></span>
<span class="line"><span>      min: 0, max: 1, step: 0.01, default: 0.5</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;rect&quot;, x: 16, y: 64, width: 140, height: 40,</span></span>
<span class="line"><span>    background: rgb(90, 140, 230),</span></span>
<span class="line"><span>    opacity: \${ui.Strength.value}, radius: 12</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>Preset</code> 字段</th><th>类型与行为</th></tr></thead><tbody><tr><td><code>dependsOn</code></td><td>必填字符串字面量，不带扩展名；例如 <code>&quot;Pogget_Std&quot;</code>、<code>&quot;MyTheme/Base&quot;</code>。只支持单层依赖，父预设必须独立，不能依赖自身</td></tr><tr><td><code>parentValues { ... }</code></td><td>可选参数表，键为父预设已有控件的完整路径，如 <code>Background.ui.CornerRadius</code>，不加 <code>.value</code> 或 <code>.default</code>；省略时保持原来的配置读取行为</td></tr><tr><td><code>disableParentPreset</code></td><td>布尔字面量，默认 <code>false</code>。<code>true</code> 时个性化页只显示子预设显式声明的自定义控件；父预设视图和控件值仍参与计算</td></tr></tbody></table><p><code>parentValues</code> 的值只接受数值、布尔或字符串字面量，包括负数；不接受引用或运算表达式，颜色可写 COLORREF 整数。类型必须与父控件默认值一致，数值必须在控件范围内，选项/颜色必须为整数；<code>TitleBlurRadius</code> 的自动值 <code>-1</code> 也是有效值。未知字段或无效值会拒绝整个新版本，并保留上一次可用预设。</p><p>父控件的值按以下顺序决定：</p><ol><li>当前收纳盒为该子预设保存的控件值。</li><li>子预设在普通组件覆盖块中显式声明的 <code>default</code> / <code>value</code>。</li><li><code>Preset.parentValues</code> 指定的值。</li><li>父控件默认值。</li></ol><p>该顺序针对 <code>parentValues</code> 列出的控件；其余带 <code>bind</code> 的控件继续读取原有原生配置。<code>parentValues</code> 中的背景、标题、边框颜色默认使用“自定义”来源，该子预设后续的颜色来源选择也独立保存。</p><p><code>disableParentPreset</code> 隐藏所有继承来的控件；子预设在同名组件的 <code>ui</code> 中显式声明的控件仍显示，包括显式覆盖的同名控件。父分组没有子预设控件时，整个折叠分组不显示。搜索同样只覆盖可显示的子控件。“高级”预设管理区仍可使用。</p><p><code>Pogget_Std</code> 的每个控件及其选项值见<a href="./standard-fields.html">完整字段表</a>。</p><h2 id="日期与当前图标" tabindex="-1">日期与当前图标 <a class="header-anchor" href="#日期与当前图标" aria-label="Permalink to &quot;日期与当前图标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>引用</th><th>返回类型与含义</th></tr></thead><tbody><tr><td><code>\${pogget.date.year}</code></td><td>数值，系统本地日期的完整年份，如 <code>2026</code></td></tr><tr><td><code>\${pogget.date.month}</code></td><td>数值，月份 <code>1..12</code></td></tr><tr><td><code>\${pogget.date.day}</code></td><td>数值，当月日期 <code>1..31</code></td></tr><tr><td><code>\${pogget.hoveredIcon.path}</code></td><td>文本，当前收纳盒中悬停图标的完整文件/文件夹路径；无悬停返回空字符串</td></tr><tr><td><code>\${pogget.selectedIcon.path}</code></td><td>文本，当前收纳盒恰好选中一个图标时的完整路径；未选中、多选或选中项失效时返回空字符串</td></tr></tbody></table><p>图标路径跟随当前普通、搜索或内联文件夹视图，编辑文档时返回空字符串；文件路径包含文件名，不是其父文件夹。它们是读取状态的输入，不会选中、打开或扫描磁盘文件。日期在绘制与现有预设轮询时刷新，跨天会触发重绘；静态文档预览的占位日期为 <code>2000/1/1</code>，图标路径为空。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DateLabel {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;text&quot;, x: 16, y: 16, width: 220, height: 28,</span></span>
<span class="line"><span>    label: \${pogget.date.year} + &quot;/&quot; + \${pogget.date.month} + &quot;/&quot; + \${pogget.date.day},</span></span>
<span class="line"><span>    textLiteral: true</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>字符串中的 <code>&quot;\${pogget.date.year}&quot;</code> 仍是普通文本；应像示例一样在字符串外引用，并用 <code>+</code> 拼接。更多输入见<a href="./inputs.html">宿主输入</a>。</p><h2 id="路径边框与滑条端点" tabindex="-1">路径边框与滑条端点 <a class="header-anchor" href="#路径边框与滑条端点" aria-label="Permalink to &quot;路径边框与滑条端点&quot;">​</a></h2><p>路径图元 <code>type: &quot;path&quot;</code> 的 <code>border</code> 默认 <code>0</code>，省略时不描边；开放路径若需要可见线条，必须显式写 <code>border: 1</code> 等正值。<code>borderColor</code>、<code>borderOpacity</code> 本身不会启用边框。关闭边框也不会关闭显式背景填充。</p><p>个性化滑条使用四舍五入显示百分比，并在拖到两端时直接取最小/最大值，修复了接近 <code>100%</code> 时显示或停留在 <code>99%</code> 的问题。</p>`,32)]))}const g=a(o,[["render",d]]);export{h as __pageData,g as default};
